contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint newMinSum, uint initialMinSum) public {
        // Set up an initial MinSum before the contract is initialized.
        c.SetMinSum(initialMinSum); if (__ESBMC_reverted()) return;
        uint minSumBefore = c.MinSum(); if (__ESBMC_reverted()) return;

        // Lock the contract so that SetMinSum can no longer change MinSum.
        c.Initialized(); if (__ESBMC_reverted()) return;

        bool setMinSumReverted;
        c.SetMinSum(newMinSum); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            setMinSumReverted = true;
        } else {
            setMinSumReverted = false;
        }

        assert(setMinSumReverted || c.MinSum() == minSumBefore);
    }

    receive() external payable {}
}

