// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 newMinSum, uint256 initialMinSum) internal {
        try c.SetMinSum(initialMinSum) {} catch { return; }
        uint256 minSumBefore;
        try c.MinSum() returns (uint256 __r) { minSumBefore = __r; } catch { return; }
        try c.Initialized() {} catch { return; }
        bool setMinSumReverted;
        try c.SetMinSum(newMinSum) {
            setMinSumReverted = false;
        } catch {
            setMinSumReverted = true;
        }
        assertTrue(setMinSumReverted || c.MinSum() == minSumBefore);
    }

    function testFuzz_run(uint256 newMinSum, uint256 initialMinSum) public {
        _run(newMinSum, initialMinSum);
    }

    receive() external payable {}
}
